(()=>{"use strict";async function t(t,e=null){const a={method:"get"};return e&&(a.method="post",a.body=e),fetch(t,a).then(t=>{if(!t.ok)throw new Error(t.status);return t.json()}).then(t=>t.data)}document.body.addEventListener("click",async e=>{const a=e.target.closest("details.liste");if(!a)return;const n=a.querySelector("[data-details]");if(!n)return;const s=parseInt(n.dataset.id);if("spell"===n.dataset.type){const e=await t("/api/get-spell?id="+s);n.innerHTML=e.fullDescription}if("avdesav"===n.dataset.type){const e=await t("/api/get-avdesav?id="+s);n.innerHTML=e.description}if("creature"===n.dataset.type){const e=await t("/api/get-creature?id="+s);n.innerHTML=e.fullDescription}})})();